def histogram(test):
    words = test.split()
    counts = {}
    for word in words:
      if word in counts:
        counts[word] += 1
      else:
        counts[word] = 1
    max_count = max(counts.values())
    return {word: count for word, count in counts.items() if count == max_count} 
